   342→    function onWheel(event) {
   343→        if (cameraMode !== CAMERA_MODES.ORBIT || !orbitState) {
   344→            return;
   345→        }
   346→        event.preventDefault();
   347→        const delta = Math.sign(event.deltaY) * 2.5;
   348→        orbitState.distance = clamp(
   349→            orbitState.distance + delta,
   350→            orbitState.minDistance,
   351→            orbitState.maxDistance
   352→        );
   353→    }
