   529→    function buildFloor(entry, span) {
   530→        const instance = makeModelInstance(entry);
   531→        if (!instance) return null;
   532→        scaleUniformToSpan(instance, span);
   533→
   534→        // Lower floor to ground (align like character)
   535→        adjustToGround(instance);
   536→
   537→        // Apply material enhancements
   538→        applyFloorMaterial(instance, entry);
   539→
   540→        return instance;
   541→    }
