   543→    function applyFloorMaterial(group, entry) {
   544→        if (!entry) return;
   545→
   546→        // Default floor material properties
   547→        const materialProps = {
   548→            roughness: entry.roughness !== undefined ? entry.roughness : 0.85,
   549→            metalness: entry.metalness !== undefined ? entry.metalness : 0.05,
   550→            envMapIntensity: entry.envMapIntensity !== undefined ? entry.envMapIntensity : 0.3
   551→        };
   552→
   553→        // Apply material properties to all meshes in floor
   554→        group.traverse(node => {
   555→            if (node.isMesh && node.material) {
   556→                const materials = Array.isArray(node.material) ? node.material : [node.material];
   557→                materials.forEach(mat => {
   558→                    if (mat && mat.isMeshStandardMaterial) {
   559→                        mat.roughness = materialProps.roughness;
   560→                        mat.metalness = materialProps.metalness;
   561→                        mat.envMapIntensity = materialProps.envMapIntensity;
   562→                        mat.needsUpdate = true;
   563→                    }
   564→                });
   565→            }
   566→        });
   567→    }
