   569→    function buildWalls(entry, span, wallHeight) {
   570→        const base = makeModelInstance(entry);
   571→        if (!base) return null;
   572→
   573→        // Skaliere Wand auf span-Breite
   574→        scaleAxisToSpan(base, 'x', span);
   575→        adjustToGround(base);
   576→
   577→        const group = new THREE.Group();
   578→
   579→        // Position walls at edge - span/2 ist Standard
   580→        const offset = span / 2;
   581→        console.log(`🧱 Building walls: span=${span}, offset=${offset}`);
   582→
   583→        const north = cloneGroup(base);
   584→        north.position.set(0, 0, -offset);
   585→        group.add(north);
   586→
   587→        const south = cloneGroup(base);
   588→        south.rotation.y = Math.PI;
   589→        south.position.set(0, 0, offset);
   590→        group.add(south);
   591→
   592→        const east = cloneGroup(base);
   593→        east.rotation.y = -Math.PI / 2;
   594→        east.position.set(offset, 0, 0);
   595→        group.add(east);
   596→
   597→        const west = cloneGroup(base);
   598→        west.rotation.y = Math.PI / 2;
   599→        west.position.set(-offset, 0, 0);
   600→        group.add(west);
   601→
   602→        group.traverse(node => {
   603→            if (node.isMesh) {
   604→                node.castShadow = true;
   605→                node.receiveShadow = true;
   606→            }
   607→        });
   608→
   609→        const scaleFactor = wallHeight / Math.max(getBoundingSize(group).y, 0.0001);
   610→        group.scale.y *= scaleFactor;
   611→        adjustToGround(group);
   612→
   613→        applyEntryTransform(group, entry);
   614→        return group;
   615→    }
