   617→    function buildProp(entry) {
   618→        const instance = makeModelInstance(entry);
   619→        if (!instance) return null;
   620→
   621→        // PERFORMANCE: Markiere Props für Frustum Culling
   622→        instance.traverse(node => {
   623→            if (node.isMesh) {
   624→                node.userData.isProp = true;
   625→            }
   626→        });
   627→
   628→        adjustToGround(instance);
   629→        applyEntryTransform(instance, entry);
   630→        return instance;
