   633→    function makeModelInstance(entry) {
   634→        if (!entry || !entry.model || !window.KayKitLoader) return null;
   635→        if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(entry.model)) return null;
   636→        const source = KayKitLoader.getModel(entry.model);
   637→        if (!source) return null;
   638→        const wrapper = new THREE.Group();
   639→        const clone = cloneObject(source);
   640→        wrapper.add(clone);
   641→
   642→        // PERFORMANCE: Shadows für alle Meshes
   643→        wrapper.traverse(node => {
   644→            if (node.isMesh) {
   645→                node.castShadow = true;
   646→                node.receiveShadow = true;
   647→            }
   648→        });
   649→
   650→        applyTint(wrapper, entry.tint);
   651→        return wrapper;
   652→    }
   653→
   654→    // SIMPLE CLONE: Use Three.js built-in clone (works reliably)
   655→    function cloneObject(object) {
   656→        if (THREE.SkeletonUtils && typeof THREE.SkeletonUtils.clone === 'function') {
   657→            return THREE.SkeletonUtils.clone(object);
   658→        }
   659→        // Fallback: Simple clone() - safe and reliable
   660→        return object.clone(true);
   661→    }
   662→
   663→    function cloneGroup(group) {
   664→        // Simple clone with deep = true
   665→        return group.clone(true);
   666→    }
   667→
   668→    function scaleUniformToSpan(group, span) {
   669→        const size = getBoundingSize(group);
   670→        const max = Math.max(size.x, size.z);
   671→        if (!max || !isFinite(max)) return;
   672→        const factor = span / max;
   673→        group.scale.multiplyScalar(factor);
   674→    }
   675→
   676→    function scaleAxisToSpan(group, axis, span) {
   677→        const size = getBoundingSize(group);
   678→        const axisSize = axis === 'z' ? size.z : size.x;
   679→        if (!axisSize || !isFinite(axisSize)) return;
   680→        const factor = span / axisSize;
   681→        if (axis === 'z') {
   682→            group.scale.z *= factor;
   683→        } else {
   684→            group.scale.x *= factor;
   685→        }
   686→    }
   687→
   688→    function getBoundingSize(group) {
   689→        const box = new THREE.Box3().setFromObject(group);
   690→        const size = new THREE.Vector3();
   691→        box.getSize(size);
   692→        return size;
   693→    }
   694→
   695→    function adjustToGround(group) {
   696→        const box = new THREE.Box3().setFromObject(group);
   697→        const center = box.getCenter(new THREE.Vector3());
