   424→function setServerStatus(online) {
   425→    if (!statusDot || !statusText) return;
   426→    if (online) {
   427→        statusDot.classList.remove('offline');
   428→        statusText.textContent = 'Online';
   429→    } else {
   430→        statusDot.classList.add('offline');
   431→        statusText.textContent = 'Offline';
   432→    }
   433→}
