   437→async function api(path, method = 'GET', body) {
   438→    const options = {
   439→        method,
   440→        headers: {'Content-Type': 'application/json'}
   441→    };
   442→    if (body) {
   443→        options.body = JSON.stringify(body);
   444→    }
   445→    try {
   446→        const response = await fetch(path, options);
   447→        if (!response.ok) {
   448→            throw new Error(response.status + ' ' + response.statusText);
   449→        }
   450→        const data = await response.json();
   451→        setServerStatus(true);
   452→        return data;
   453→    } catch (error) {
   454→        setServerStatus(false);
   455→        throw error;
   456→    }
   457→}
