     1→// MINIGAMES MODULE v2
     2→(function() {
     3→    let currentGame = null;
     4→    let score = 0;
     5→    let gameInterval = null;
     6→    let cleanupFn = null;
     7→    let frameHandle = null;
     8→    const timeouts = new Set();
     9→    let currentGameLabel = '';
    10→    function scheduleTimeout(handler, delay) {
    11→        const id = setTimeout(() => {
    12→            timeouts.delete(id);
    13→            handler();
    14→        }, delay);
    15→        timeouts.add(id);
    16→        return id;
    17→    }
    18→    function cancelTimeout(id) {
    19→        if (timeouts.has(id)) {
    20→            clearTimeout(id);
    21→            timeouts.delete(id);
    22→        }
    23→    }
    24→    function clamp(value, min, max) {
    25→        return Math.min(max, Math.max(min, value));
    26→    }
    27→    function clearTimers() {
    28→        if (gameInterval) {
    29→            clearInterval(gameInterval);
    30→            gameInterval = null;
    31→        }
    32→        if (frameHandle) {
    33→            cancelAnimationFrame(frameHandle);
    34→            frameHandle = null;
    35→        }
    36→        timeouts.forEach(id => clearTimeout(id));
    37→        timeouts.clear();
    38→    }
    39→    function setCleanup(fn) {
    40→        cleanupFn = fn;
    41→    }
    42→    function createOverlay() {
    43→        if (document.getElementById('minigameOverlay')) return;
    44→        const overlay = document.createElement('div');
    45→        overlay.id = 'minigameOverlay';
    46→        overlay.className = 'minigame-overlay';
    47→        overlay.innerHTML = `
    48→            <div class="minigame-container">
    49→                <div class="minigame-header">
    50→                    <h2 id="minigameTitle">Minigame</h2>
    51→                    <div class="minigame-score">Score: <span id="minigameScore">0</span></div>
    52→                    <button class="minigame-close" onclick="MiniGames.close()">×</button>
    53→                </div>
    54→                <div class="minigame-content" id="minigameContent"></div>
    55→            </div>
    56→        `;
    57→        document.body.appendChild(overlay);
    58→    }
    59→    function updateScore(points = 0, reset = false) {
    60→        if (reset) {
    61→            score = 0;
    62→        } else {
    63→            score += points;
    64→        }
    65→        const scoreEl = document.getElementById('minigameScore');
    66→        if (scoreEl) {
    67→            scoreEl.textContent = Math.max(0, Math.round(score));
    68→        }
    69→    }
    70→    function open(gameName) {
    71→        createOverlay();
    72→        const overlay = document.getElementById('minigameOverlay');
    73→        const content = document.getElementById('minigameContent');
    74→        const title = document.getElementById('minigameTitle');
    75→        clearTimers();
    76→        if (cleanupFn) {
    77→            cleanupFn();
    78→            cleanupFn = null;
    79→        }
    80→        score = 0;
    81→        updateScore(0, true);
    82→        setCleanup(null);
    83→        overlay.classList.add('active');
    84→        currentGame = gameName;
    85→        currentGameLabel = 'Minigame';
    86→        switch (gameName) {
    87→            case 'rhythm':
    88→                title.textContent = '🎵 Rhythmus-Spiel';
    89→                currentGameLabel = title.textContent;
    90→                startRhythmGame(content);
    91→                break;
    92→            case 'garden':
    93→                title.textContent = '🌿 Garten-Spiel';
    94→                currentGameLabel = title.textContent;
    95→                startGardenGame(content);
    96→                break;
    97→            case 'reflex':
    98→                title.textContent = '⚡ Reflex-Spiel';
    99→                currentGameLabel = title.textContent;
   100→                startReflexGame(content);
   101→                break;
   102→            case 'broom':
   103→                title.textContent = '🧹 Besen-Lieferung';
   104→                currentGameLabel = title.textContent;
   105→                startBroomGame(content);
   106→                break;
   107→            case 'craft':
   108→                title.textContent = '🛠️ Crafting-Workshop';
   109→                currentGameLabel = title.textContent;
   110→                startCraftingGame(content);
   111→                break;
   112→            case 'training':
   113→                title.textContent = '🥋 Trainings-Dojō';
   114→                currentGameLabel = title.textContent;
   115→                startTrainingGame(content);
   116→                break;
   117→            case 'cooking':
   118→                title.textContent = '🍳 Najikas Hexenküche';
   119→                currentGameLabel = title.textContent;
   120→                startCookingGame(content);
   121→                break;
   122→            default:
   123→                title.textContent = '🎮 Minigame';
   124→                currentGameLabel = title.textContent;
