   289→    /* === BROOM DELIVERY GAME === */
   290→    function startBroomGame(content) {
   291→        content.innerHTML = `
   292→            <div class="broom-game">
   293→                <canvas id="broomCanvas" width="720" height="400"></canvas>
   294→                <div class="broom-hud">
   295→                    <span>🧹 Leben: <span id="broomLives">3</span></span>
   296→                    <span>📦 Lieferungen: <span id="broomDeliveries">0</span></span>
   297→                    <span>⏳ <span id="broomTimer">60</span>s</span>
   298→                    <p>Steuerung: W / S oder Pfeile ↑ ↓ · SPACE liefert Hexenpost</p>
   299→                </div>
   300→            </div>
   301→        `;
   302→        const canvas = document.getElementById('broomCanvas');
   303→        const ctx = canvas.getContext('2d');
   304→        const livesEl = document.getElementById('broomLives');
   305→        const deliveriesEl = document.getElementById('broomDeliveries');
   306→        const timerEl = document.getElementById('broomTimer');
   307→        const player = { x: 90, y: canvas.height / 2, width: 42, height: 22 };
   308→        const packages = [];
   309→        const houses = [];
   310→        const keys = new Set();
   311→        let lives = 3;
   312→        let deliveries = 0;
   313→        let timer = 60;
   314→        let lastThrow = 0;
   315→        let running = true;
   316→        function spawnHouse() {
   317→            const doorY = 110 + Math.random() * (canvas.height - 180);
   318→            houses.push({
   319→                x: canvas.width + Math.random() * 220 + 200,
   320→                y: doorY,
   321→                width: 70,
   322→                height: 120
   323→            });
   324→        }
   325→        while (houses.length < 4) {
   326→            spawnHouse();
   327→        }
   328→        function updateHud() {
   329→            livesEl.textContent = Math.max(0, lives);
   330→            deliveriesEl.textContent = deliveries;
   331→            timerEl.textContent = Math.max(0, timer);
   332→        }
   333→        function throwPackage() {
   334→            const now = performance.now();
   335→            if (now - lastThrow < 400) return;
   336→            lastThrow = now;
   337→            packages.push({
   338→                x: player.x + 28,
   339→                y: player.y,
   340→                vx: 6.2,
   341→                vy: 0
   342→            });
   343→        }
   344→        function drawBackground() {
   345→            const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
   346→            gradient.addColorStop(0, '#05021d');
   347→            gradient.addColorStop(1, '#0f3057');
   348→            ctx.fillStyle = gradient;
   349→            ctx.fillRect(0, 0, canvas.width, canvas.height);
   350→            ctx.fillStyle = 'rgba(255,255,255,0.5)';
   351→            for (let i = 0; i < 60; i++) {
   352→                const x = (i * 73 + performance.now() * 0.02) % canvas.width;
   353→                const y = (i * 53) % canvas.height;
   354→                ctx.fillRect(x, y, 2, 2);
   355→            }
   356→        }
   357→        function drawPlayer() {
   358→            ctx.save();
   359→            ctx.translate(player.x, player.y);
   360→            ctx.fillStyle = '#452b7c';
   361→            ctx.beginPath();
   362→            ctx.ellipse(0, 0, 24, 16, 0, 0, Math.PI * 2);
   363→            ctx.fill();
   364→            ctx.fillStyle = '#ffcf40';
   365→            ctx.fillRect(12, -4, 26, 8);
   366→            ctx.fillStyle = '#c08457';
   367→            ctx.fillRect(28, -8, 18, 16);
   368→            ctx.restore();
   369→        }
   370→        function drawHouse(house) {
   371→            ctx.save();
   372→            ctx.translate(house.x, house.y);
   373→            ctx.fillStyle = '#2f2a4a';
   374→            ctx.fillRect(-house.width / 2, -house.height / 2, house.width, house.height);
   375→            ctx.fillStyle = '#1b5e20';
   376→            ctx.fillRect(-house.width / 2, house.height / 2 - 50, house.width, 50);
   377→            ctx.fillStyle = '#ffea00';
   378→            ctx.fillRect(-15, 10, 30, 40);
   379→            ctx.restore();
   380→        }
   381→        function gameLoop() {
   382→            if (!running) return;
   383→            frameHandle = requestAnimationFrame(gameLoop);
   384→            drawBackground();
   385→            if (keys.has('ArrowUp') || keys.has('KeyW')) player.y -= 4;
   386→            if (keys.has('ArrowDown') || keys.has('KeyS')) player.y += 4;
   387→            player.y = clamp(player.y, 50, canvas.height - 50);
   388→            drawPlayer();
   389→            const speed = 3.2 + deliveries * 0.04;
   390→            houses.forEach(house => {
   391→                house.x -= speed;
   392→                drawHouse(house);
   393→                if (house.x < -120) {
   394→                    lives -= 1;
   395→                    house.x = canvas.width + Math.random() * 220 + 200;
   396→                    house.y = 110 + Math.random() * (canvas.height - 180);
   397→                }
   398→            });
   399→            for (let i = packages.length - 1; i >= 0; i--) {
   400→                const pkg = packages[i];
   401→                pkg.x += pkg.vx;
   402→                pkg.y += pkg.vy;
   403→                ctx.fillStyle = '#ff7043';
   404→                ctx.fillRect(pkg.x - 6, pkg.y - 6, 12, 12);
   405→                if (pkg.x > canvas.width + 40) {
   406→                    packages.splice(i, 1);
   407→                    continue;
   408→                }
   409→                houses.forEach(house => {
   410→                    const doorY = house.y + house.height / 2 - 20;
   411→                    if (
   412→                        pkg.x > house.x - house.width / 2 &&
   413→                        pkg.x < house.x + house.width / 2 &&
   414→                        Math.abs(pkg.y - doorY) < 30
   415→                    ) {
   416→                        deliveries += 1;
   417→                        updateScore(15);
   418→                        packages.splice(i, 1);
   419→                        house.x = canvas.width + Math.random() * 220 + 220;
   420→                        house.y = 110 + Math.random() * (canvas.height - 180);
   421→                    }
   422→                });
   423→            }
   424→            if (lives <= 0) {
   425→                running = false;
   426→                triggerExplosion(content);
   427→            }
   428→            updateHud();
   429→        }
   430→        function triggerExplosion(contentContainer) {
   431→            clearTimers();
   432→            const splash = document.createElement('div');
   433→            splash.className = 'broom-explosion';
   434→            splash.innerHTML = `
   435→                <h3>💥 EXPLOSION!</h3>
   436→                <p>Najika rastet aus und jagt die Welt mit einer Explosion in die Luft!</p>
   437→            `;
   438→            contentContainer.appendChild(splash);
   439→            scheduleTimeout(() => close(), 2500);
   440→        }
   441→        function tickTimer() {
   442→            timer -= 1;
   443→            updateHud();
   444→            if (timer <= 0) {
   445→                running = false;
   446→                const banner = document.createElement('div');
   447→                banner.className = 'broom-success';
   448→                banner.innerHTML = '<h3>✨ Alle Lieferungen geschafft!</h3><p>Najika ist zufrieden.</p>';
   449→                content.appendChild(banner);
   450→                scheduleTimeout(() => close(), 1500);
   451→            }
   452→        }
   453→        const keyDown = (e) => {
   454→            if (['ArrowUp', 'ArrowDown', 'KeyW', 'KeyS'].includes(e.code)) {
   455→                keys.add(e.code);
   456→                e.preventDefault();
   457→            }
   458→            if (e.code === 'Space' || e.code === 'Enter') {
   459→                throwPackage();
   460→                e.preventDefault();
   461→            }
   462→        };
   463→        const keyUp = (e) => {
   464→            if (['ArrowUp', 'ArrowDown', 'KeyW', 'KeyS'].includes(e.code)) {
   465→                keys.delete(e.code);
   466→                e.preventDefault();
   467→            }
   468→        };
   469→        window.addEventListener('keydown', keyDown);
   470→        window.addEventListener('keyup', keyUp);
   471→        setCleanup(() => {
   472→            window.removeEventListener('keydown', keyDown);
   473→            window.removeEventListener('keyup', keyUp);
   474→        });
   475→        frameHandle = requestAnimationFrame(gameLoop);
   476→        gameInterval = setInterval(tickTimer, 1000);
   477→        updateHud();
   478→    }
