   680→        function spawnItem() {
   681→            // 70% Chance für Rezept-Zutat, 30% für "falsche" Zutat
   682→            const isRecipeItem = Math.random() > 0.3;
   683→            const ingredient = isRecipeItem
   684→                ? currentRecipe.ingredients[Math.floor(Math.random() * currentRecipe.ingredients.length)]
   685→                : ['💀', '🔥', '❌', '💣'][Math.floor(Math.random() * 4)];
   686→
   687→            const x = Math.random() * (canvas.width - 100) + 50;
   688→            const vy = -(10 + Math.random() * 6);
   689→            const vx = (Math.random() - 0.5) * 8;
   690→
   691→            items.push({
   692→                x,
   693→                y: canvas.height + 20,
   694→                vx,
   695→                vy,
   696→                gravity: 0.4,
   697→                icon: ingredient,
   698→                isRecipe: isRecipeItem && currentRecipe.ingredients.includes(ingredient),
   699→                isWrong: !isRecipeItem,
   700→                rotation: 0,
   701→                rotationSpeed: (Math.random() - 0.5) * 0.2,
   702→                size: 50
   703→            });
   704→        }
   705→
   706→        function drawItem(item) {
   707→            ctx.save();
   708→            ctx.translate(item.x, item.y);
   709→            ctx.rotate(item.rotation);
   710→            ctx.font = `${item.size}px Arial`;
   711→            ctx.textAlign = 'center';
   712→            ctx.textBaseline = 'middle';
   713→            ctx.fillText(item.icon, 0, 0);
   714→            ctx.restore();
   715→        }
   716→
   717→        function drawSlicePaths() {
   718→            slicePaths.forEach((path, idx) => {
   719→                ctx.strokeStyle = `rgba(255, 100, 100, ${1 - idx / slicePaths.length})`;
   720→                ctx.lineWidth = 4;
   721→                ctx.lineCap = 'round';
   722→                ctx.beginPath();
   723→                path.points.forEach((pt, i) => {
   724→                    if (i === 0) ctx.moveTo(pt.x, pt.y);
   725→                    else ctx.lineTo(pt.x, pt.y);
   726→                });
   727→                ctx.stroke();
   728→            });
   729→        }
   730→
   731→        function checkSlice(sliceX, sliceY) {
   732→            for (let i = items.length - 1; i >= 0; i--) {
   733→                const item = items[i];
   734→                const dx = item.x - sliceX;
   735→                const dy = item.y - sliceY;
   736→                const distance = Math.sqrt(dx * dx + dy * dy);
   737→
   738→                if (distance < item.size / 2 + 20) {
   739→                    // Treffer!
   740→                    items.splice(i, 1);
   741→
   742→                    if (item.isWrong) {
   743→                        // Falsche Zutat geschnitten → Verliere Leben
   744→                        lives -= 1;
   745→                        combo = 0;
   746→                        updateHud();
   747→                        createParticles(item.x, item.y, '💥');
   748→                        if (lives <= 0) {
   749→                            endGame('💀 Najika hat sich vergiftet!');
   750→                            return;
   751→                        }
   752→                    } else if (item.isRecipe) {
   753→                        // Richtige Zutat!
   754→                        if (!collected.includes(item.icon)) {
   755→                            collected.push(item.icon);
   756→                            renderRecipeDisplay();
   757→                        }
   758→                        combo += 1;
   759→                        updateScore(10 + combo * 3);
   760→                        updateHud();
   761→                        createParticles(item.x, item.y, '✨');
   762→
   763→                        // Rezept komplett?
   764→                        if (collected.length >= currentRecipe.ingredients.length) {
   765→                            finishRecipe();
   766→                        }
   767→                    }
   768→                }
   769→            }
   770→        }
   771→
   772→        function createParticles(x, y, icon) {
   773→            for (let i = 0; i < 6; i++) {
   774→                const angle = (i / 6) * Math.PI * 2;
   775→                const speed = 3 + Math.random() * 2;
   776→                items.push({
   777→                    x,
   778→                    y,
   779→                    vx: Math.cos(angle) * speed,
   780→                    vy: Math.sin(angle) * speed - 2,
   781→                    gravity: 0.2,
   782→                    icon,
   783→                    size: 20,
   784→                    rotation: 0,
   785→                    rotationSpeed: 0.1,
   786→                    isParticle: true
   787→                });
   788→            }
   789→        }
   790→
   791→        function finishRecipe() {
   792→            updateScore(50);
   793→            combo = 0;
   794→            collected = [];
   795→            currentRecipe = recipes[Math.floor(Math.random() * recipes.length)];
   796→            recipeNameEl.textContent = currentRecipe.name + ' ' + currentRecipe.icon;
   797→            renderRecipeDisplay();
   798→            updateHud();
   799→        }
   800→
   801→        function endGame(message) {
   802→            clearTimers();
   803→            ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
   804→            ctx.fillRect(0, 0, canvas.width, canvas.height);
   805→            ctx.fillStyle = '#fff';
   806→            ctx.font = '36px Arial';
   807→            ctx.textAlign = 'center';
   808→            ctx.fillText(message, canvas.width / 2, canvas.height / 2);
   809→            scheduleTimeout(() => close(), 2000);
   810→        }
   811→
   812→        function updateHud() {
   813→            livesEl.textContent = Math.max(0, lives);
   814→            comboEl.textContent = combo;
   815→            progressEl.textContent = `${collected.length}/${currentRecipe.ingredients.length}`;
   816→        }
   817→
   818→        function gameLoop() {
   819→            if (!canvas.isConnected) return;
   820→            frameHandle = requestAnimationFrame(gameLoop);
   821→
   822→            // Clear
   823→            const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
   824→            gradient.addColorStop(0, '#1a0808');
   825→            gradient.addColorStop(1, '#0f1722');
   826→            ctx.fillStyle = gradient;
   827→            ctx.fillRect(0, 0, canvas.width, canvas.height);
   828→
   829→            // Update items
   830→            for (let i = items.length - 1; i >= 0; i--) {
   831→                const item = items[i];
   832→                item.vy += item.gravity;
   833→                item.x += item.vx;
   834→                item.y += item.vy;
   835→                item.rotation += item.rotationSpeed;
   836→
   837→                // Entferne Items die unten raus fallen
   838→                if (item.y > canvas.height + 60) {
   839→                    items.splice(i, 1);
   840→                    if (!item.isParticle && item.isRecipe) {
   841→                        lives -= 1;
   842→                        combo = 0;
   843→                        updateHud();
   844→                        if (lives <= 0) {
   845→                            endGame('😵 Alle Zutaten verpasst!');
   846→                            return;
   847→                        }
   848→                    }
   849→                    continue;
   850→                }
   851→
   852→                drawItem(item);
   853→            }
   854→
   855→            // Draw slice paths
   856→            drawSlicePaths();
   857→
   858→            // Fade out old slices
   859→            slicePaths = slicePaths.filter(path => path.age++ < 15);
   860→        }
   861→
   862→        // Mouse/Touch Controls
   863→        const getPos = (e) => {
   864→            const rect = canvas.getBoundingClientRect();
   865→            const clientX = e.clientX || (e.touches && e.touches[0]?.clientX);
   866→            const clientY = e.clientY || (e.touches && e.touches[0]?.clientY);
   867→            return {
   868→                x: (clientX - rect.left) * (canvas.width / rect.width),
   869→                y: (clientY - rect.top) * (canvas.height / rect.height)
   870→            };
   871→        };
   872→
   873→        const onStart = (e) => {
   874→            isSlicing = true;
   875→            const pos = getPos(e);
   876→            sliceStart = pos;
