   506→                    node.material = node.material.clone();
   507→                    node.material.side = THREE.DoubleSide;
   508→                    if (node.material.map) {
   509→                        node.material.map.encoding = THREE.sRGBEncoding;
   510→                        node.material.map.needsUpdate = true;
   511→                    }
   512→                }
   513→                node.castShadow = true;
   514→                node.receiveShadow = true;
   515→            }
   516→        });
   517→        if (options.scale) {
   518→            if (Array.isArray(options.scale) && options.scale.length === 3) {
   519→                clone.scale.set(options.scale[0], options.scale[1], options.scale[2]);
   520→            } else if (typeof options.scale === 'number') {
   521→                clone.scale.multiplyScalar(options.scale);
   522→            }
   523→        }
   524→        if (options.targetSpan) {
   525→            const sizeBefore = new THREE.Box3().setFromObject(clone).getSize(new THREE.Vector3());
   526→            const spanBefore = Math.max(sizeBefore.x, sizeBefore.z, 0.0001);
   527→            const factor = options.targetSpan / spanBefore;
   528→            clone.scale.multiplyScalar(factor);
   529→        }
   530→        if (options.rotation) {
   531→            const rot = normalizeVector(options.rotation, 0);
   532→            clone.rotation.set(rot[0], rot[1], rot[2]);
   533→        }
   534→        const bbox = new THREE.Box3().setFromObject(clone);
   535→        const center = bbox.getCenter(new THREE.Vector3());
   536→        const size = bbox.getSize(new THREE.Vector3());
   537→        clone.position.sub(center);
   538→        clone.position.y += size.y / 2;
   539→        if (options.position) {
   540→            const pos = normalizeVector(options.position, 0);
   541→            clone.position.x += pos[0];
   542→            clone.position.y += pos[1];
   543→            clone.position.z += pos[2];
   544→        }
   545→        if (options.tint) {
   546→            applyTint(clone, parseColor(options.tint, null));
   547→        }
   548→        return { object: clone, size };
   549→    }
