   604→            orbitTime += delta;
   605→            const t = orbitTime * 0.5;
   606→            camera.position.x = Math.sin(t * 0.8) * 8;
   607→            camera.position.z = 12 + Math.cos(t * 0.6) * 3;
   608→            camera.position.y = 5 + Math.sin(t) * 0.8;
   609→            camera.lookAt(0, 2, 0);
   610→            return;
   611→        }
   612→        const forwardDir = new THREE.Vector3(Math.sin(characterHeading), 0, -Math.cos(characterHeading));
   613→        const eyeTarget = characterGroup.position.clone().add(new THREE.Vector3(0, characterHeight * 0.85, 0));
   614→        if (cameraMode === CAMERA_MODES.THIRD) {
   615→            const followOffset = forwardDir.clone().multiplyScalar(-18);
   616→            const desiredPosition = eyeTarget.clone().add(new THREE.Vector3(0, 4, 0)).add(followOffset);
