  1282→            if (Array.isArray(options.scale) && options.scale.length === 3) {
  1283→                clone.scale.set(options.scale[0], options.scale[1], options.scale[2]);
  1284→            } else if (typeof options.scale === 'number') {
  1285→                clone.scale.multiplyScalar(options.scale);
  1286→            }
  1287→        }
  1288→        if (options.targetSpan) {
  1289→            const sizeBefore = new THREE.Box3().setFromObject(clone).getSize(new THREE.Vector3());
  1290→            const spanBefore = Math.max(sizeBefore.x, sizeBefore.z, 0.0001);
  1291→            const factor = options.targetSpan / spanBefore;
  1292→            clone.scale.multiplyScalar(factor);
  1293→        }
