  1299→        const center = bbox.getCenter(new THREE.Vector3());
  1300→        const size = bbox.getSize(new THREE.Vector3());
  1301→        clone.position.sub(center);
  1302→        clone.position.y += size.y / 2;
  1303→        if (options.position) {
  1304→            const pos = normalizeVector(options.position, 0);
  1305→            clone.position.x += pos[0];
  1306→            clone.position.y += pos[1];
  1307→            clone.position.z += pos[2];
  1308→        }
