﻿/* MINIGAME OVERLAY */
.minigame-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.95);
    backdrop-filter: blur(10px);
    z-index: 10000;
    display: none;
    align-items: center;
    justify-content: center;
    animation: fadeIn 0.3s ease;
}

.minigame-overlay.active {
    display: flex;
}

.minigame-container {
    width: 90%;
    max-width: 800px;
    height: 80vh;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    border-radius: 20px;
    border: 3px solid #667eea;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.minigame-header {
    padding: 1rem 1.5rem;
    background: linear-gradient(135deg, #667eea, #764ba2);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.minigame-header h2 {
    font-size: 1.3rem;
    margin: 0;
}

.minigame-score {
    font-size: 1.5rem;
    font-weight: bold;
}

.minigame-close {
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.4rem;
    transition: all 0.3s;
}

.minigame-close:hover {
    background: rgba(255, 255, 255, 0.3);
    transform: rotate(90deg);
}

.minigame-content {
    flex: 1;
    position: relative;
    overflow: hidden;
}

/* RHYTHM GAME */
.rhythm-game {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2rem;
}

.rhythm-track {
    width: 80%;
    height: 400px;
    position: relative;
    background: rgba(0, 0, 0, 0.3);
    border-radius: 10px;
    overflow: hidden;
}

.rhythm-note {
    position: absolute;
    width: 60px;
    height: 60px;
    background: linear-gradient(135deg, #f093fb, #f5576c);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;

