function updateCamera() {
    if (!camera) return;
    if (cameraMode === CAMERA_MODES.ORBIT) {
        if (!orbitState) return;
        updateOrbitTarget();
        const target = orbitState.target;
        const radius = orbitState.distance;
        const sinPhi = Math.sin(orbitState.phi);
        const cosPhi = Math.cos(orbitState.phi);
        const sinTheta = Math.sin(orbitState.theta);
        const cosTheta = Math.cos(orbitState.theta);
        camera.position.set(
            target.x + radius * sinPhi * sinTheta,
            target.y + radius * cosPhi,
            target.z + radius * sinPhi * cosTheta
        );
        camera.lookAt(target.x, target.y + CHARACTER_HEIGHT * 0.5, target.z);
    } else if (cameraMode === CAMERA_MODES.THIRD) {
        const base = characterGroup ? characterGroup.position : new THREE.Vector3();
        const offset = 12;
        const height = CHARACTER_HEIGHT + 3.5;
        camera.position.set(
            base.x - Math.sin(characterHeading) * offset,
            base.y + height,
            base.z - Math.cos(characterHeading) * offset
        );
        camera.lookAt(base.x, base.y + CHARACTER_HEIGHT * 0.8, base.z);
    } else {
        const base = characterGroup ? characterGroup.position : new THREE.Vector3();
        const eye = CHARACTER_HEIGHT - 0.15;
        camera.position.set(base.x, base.y + eye, base.z);
        camera.lookAt(
            base.x + Math.sin(characterHeading),
            base.y + eye,
            base.z + Math.cos(characterHeading)
        );
    }
}

function updateOrbitTarget() {
    if (!orbitState) return;
    if (characterGroup) {
        orbitState.target.copy(characterGroup.position);
        orbitState.target.y += 1.2;
    } else {
        orbitState.target.set(0, 0, 0);
    }
}

