function getCameraTarget() {
    if (characterGroup) {
        return characterGroup.position.clone().add(new THREE.Vector3(0, CHARACTER_HEIGHT * 0.85, 0));
    }
    return new THREE.Vector3(0, 0, 0);
}

function updateCamera(delta) {
    if (!camera) return;

    const target = getCameraTarget();

    // ORBIT Mode: Manuelle Kamera-Steuerung (dreht NICHT automatisch mit WASD)
    if (cameraMode === CAMERA_MODES.ORBIT || !characterGroup) {
        const cosPitch = Math.cos(orbitPitch);
        const offset = new THREE.Vector3(
            Math.sin(orbitYaw) * cosPitch,
            Math.sin(orbitPitch),
            Math.cos(orbitYaw) * cosPitch
        ).multiplyScalar(orbitDistance);
        camera.position.copy(target).add(offset);
        camera.lookAt(target);
        return;
    }

    // THIRD Person: Folgt dem Character von hinten (dreht MIT WASD)
    const forwardDir = new THREE.Vector3(Math.sin(characterHeading), 0, -Math.cos(characterHeading));
    const basePos = characterGroup ? characterGroup.position.clone() : new THREE.Vector3();

    if (cameraMode === CAMERA_MODES.THIRD) {
        const followOffset = forwardDir.clone().multiplyScalar(-18);
        const desiredPosition = basePos.clone().add(new THREE.Vector3(0, 4, 0)).add(followOffset);
        camera.position.lerp(desiredPosition, Math.min(delta * 6, 1));
        camera.lookAt(target);
    } else if (cameraMode === CAMERA_MODES.FIRST) {
        // FIRST Person: Direkt hinter den Augen
        const eyePosition = target.clone()
            .add(new THREE.Vector3(0, -CHARACTER_HEIGHT * 0.15, 0))
            .add(forwardDir.clone().multiplyScalar(1.8));
        const lookPoint = target.clone().add(forwardDir.clone().multiplyScalar(6));
        camera.position.copy(eyePosition);
        camera.lookAt(lookPoint);
    }
}

