function onPointerDown(event) {
    if (
        cameraMode !== CAMERA_MODES.ORBIT ||
        !orbitState ||
        orbitState.isDragging
    ) {
        return;
    }
    orbitState.isDragging = true;
    orbitState.pointerId = event.pointerId;
    orbitState.lastX = event.clientX;
    orbitState.lastY = event.clientY;
    event.target.setPointerCapture(event.pointerId);
}

function onPointerMove(event) {
    if (
        cameraMode !== CAMERA_MODES.ORBIT ||
        !orbitState ||
        !orbitState.isDragging ||
        orbitState.pointerId !== event.pointerId
    ) {
        return;
    }
    const dx = event.clientX - orbitState.lastX;
    const dy = event.clientY - orbitState.lastY;
    orbitState.lastX = event.clientX;
    orbitState.lastY = event.clientY;
    orbitState.theta -= dx * 0.005;
    orbitState.phi = clamp(
        orbitState.phi - dy * 0.005,
        orbitState.minPhi,
        orbitState.maxPhi
    );
}

function onPointerUp(event) {
    if (
        cameraMode !== CAMERA_MODES.ORBIT ||
        !orbitState ||
        !orbitState.isDragging ||
        orbitState.pointerId !== event.pointerId
    ) {
        return;
    }
    orbitState.isDragging = false;
    orbitState.pointerId = null;
    if (event.target.releasePointerCapture) {
        event.target.releasePointerCapture(event.pointerId);
    }
}

function onWheel(event) {
    if (cameraMode !== CAMERA_MODES.ORBIT || !orbitState) {
        return;
    }
    event.preventDefault();
    const delta = Math.sign(event.deltaY) * 2.5;
    orbitState.distance = clamp(
        orbitState.distance + delta,
        orbitState.minDistance,
        orbitState.maxDistance
    );
}

